package cn.fuzhu.toolkit.modules;
import cn.fuzhu.toolkit.FuzhuToolkitPlugin; import cn.fuzhu.toolkit.module.AbstractModule; import org.bukkit.command.*; import org.bukkit.event.*; import org.bukkit.event.player.PlayerJoinEvent;
public class WelcomeModule extends AbstractModule { private Listener listener; public WelcomeModule(FuzhuToolkitPlugin p){super(p);config=p.moduleConfig(id());} public String id(){return "Welcome";} public String description(){return "彩色欢迎消息";} public void enable(){super.enable();listener=new Listener(){@EventHandler public void join(PlayerJoinEvent e){String m=plugin.getConfig().getString("welcome-message","&b欢迎 &f%player% &b加入服务器！").replace("%player%",e.getPlayer().getName());e.setJoinMessage(plugin.color(m));}};plugin.getServer().getPluginManager().registerEvents(listener,plugin);} public void disable(){if(listener!=null)HandlerList.unregisterAll(listener);super.disable();} public boolean handle(CommandSender s,String l,String[] a){plugin.msg(s,"&7本模块无需命令。");return true;} }
